import com.google.gson.*;
import java.io.IOException;
import java.util.*;

/** Engine-observed manual casting acceptance, with no rule or response-selection implementation. */
public final class NativeCastingCase implements NativeAcceptanceCase {
    private final String key,name,land;private final Map<String,Long> selected=new LinkedHashMap<>(),stacked=new HashMap<>();
    private final Set<String> pileChosen=new HashSet<>(),pileRejected=new HashSet<>();private boolean pileAnswered,pileFirst,pileVerified;
    private final Set<String> paidSources=new HashSet<>();private boolean colorlessSeen;
    private String viewer,cancelledSource,creature,counterSource;private long counterIncarnation=-1;private final Set<String> ownSpells=new HashSet<>();private boolean counterTargeted,searchVerified;private long searchLibrary=-1,searchTurn=-1;private final Set<String> searchHand=new HashSet<>();private long creatureIncarnation=-1;private int payments,numbers;private boolean cancelled,completed,verified,activated,floatingSeen;private long floatingTurn=-1;
    public NativeCastingCase(String key) {
        if(!Arrays.asList("casting-repeat","casting-cancel","casting-x","casting-ability","casting-green","casting-blue","casting-generic","casting-floating","casting-modes","casting-additional","casting-mixed","casting-countered","casting-search","casting-hybrid","casting-phyrexian","casting-colorless","casting-kicker","casting-discount","casting-pile","casting-x-zero").contains(key))throw new IllegalArgumentException("CASTING_CASE_INVALID");
        this.key=key;land=key.equals("casting-colorless")?"Wastes":(key.equals("casting-blue") || key.equals("casting-pile"))?"Island":key.equals("casting-additional")?"Mountain":"Forest";name=key.equals("casting-pile")?"Fact or Fiction":key.equals("casting-hybrid")?"Slitherhead":key.equals("casting-phyrexian")?"Vault Skirge":key.equals("casting-colorless")?"Matter Reshaper":key.equals("casting-kicker")?"Kavu Titan":key.equals("casting-discount")?"Frogmite":(key.equals("casting-modes") || key.equals("casting-search"))?"Evolution Charm":key.equals("casting-additional")?"Fling":key.equals("casting-repeat")?"Memnite":key.equals("casting-cancel")?"Garruk's Companion":key.equals("casting-green") || key.equals("casting-floating")?"Sedge Scorpion":key.equals("casting-blue")?"Coral Merfolk":(key.equals("casting-generic") || key.equals("casting-mixed") || key.equals("casting-countered"))?"Centaur Courser":"Walking Ballista";
    }
    public String key(){return key;}
    public JsonArray deck(boolean ai) {
        JsonArray result=new JsonArray();for(int i=0;i<60;i++) {
            String card=ai?(key.equals("casting-countered")?(i%2==0?"Island":"Counterspell"):"Forest"):key.equals("casting-mixed")?new String[]{"Forest","Island",name}[i%3]:key.equals("casting-discount") || key.equals("casting-modes") || key.equals("casting-additional")?new String[]{land,"Memnite",name}[i%3]:i%2==0?land:name;
            String set=card.equals("Fact or Fiction")?"INV":card.equals("Wastes") || card.equals("Matter Reshaper")?"OGW":card.equals("Slitherhead")?"RTR":card.equals("Vault Skirge")?"NPH":card.equals("Kavu Titan")?"INV":card.equals("Frogmite")?"MRD":card.equals("Forest") || card.equals("Island") || card.equals("Mountain")?"TRK":card.equals("Evolution Charm")?"PLC":card.equals("Counterspell")?"7ED":card.equals("Fling")?"ELD":card.equals("Memnite")?"SOM":card.equals("Garruk's Companion")?"M12":card.equals("Sedge Scorpion") || card.equals("Coral Merfolk") || card.equals("Centaur Courser")?"M20":"AER";
            String number=card.equals("Fact or Fiction")?"57":card.equals("Wastes")?"184":card.equals("Matter Reshaper")?"6":card.equals("Slitherhead")?"222":card.equals("Vault Skirge")?"76":card.equals("Kavu Titan")?"194":card.equals("Frogmite")?"172":card.equals("Forest")?"325":card.equals("Island")?"319":card.equals("Mountain")?"323":card.equals("Evolution Charm")?"127":card.equals("Counterspell")?"67":card.equals("Fling")?"126":card.equals("Memnite")?"174":card.equals("Garruk's Companion")?"175":card.equals("Sedge Scorpion")?"192":card.equals("Coral Merfolk")?"315":card.equals("Centaur Courser")?"168":"181";
            JsonObject row=new JsonObject();row.addProperty("name",card);row.addProperty("set",set);row.addProperty("number",number);row.addProperty("quantity",1);result.add(row);
        }return result;
    }
    public boolean openingMatches(JsonArray hand){Set<String> seen=new HashSet<>();for(JsonElement item:hand){String value=text(item.getAsJsonObject(),"name");if(!value.equals(name) && !value.equals(land) && !(key.equals("casting-mixed") && value.equals("Island")) && !((key.equals("casting-discount") || key.equals("casting-modes") || key.equals("casting-additional")) && value.equals("Memnite")))return false;seen.add(value);}return seen.contains(name) && seen.contains(land);}
    private static String text(JsonObject row,String key){JsonElement value=row.get(key);return value==null || value.isJsonNull()?"":value.getAsString();}
    private static JsonObject locate(JsonObject state,String id,String zone){JsonArray cards=state.getAsJsonArray(zone);if(cards!=null)for(JsonElement card:cards)if(id.equals(text(card.getAsJsonObject(),"id")))return card.getAsJsonObject();for(JsonElement player:state.getAsJsonArray("players")){cards=player.getAsJsonObject().getAsJsonArray(zone);if(cards!=null)for(JsonElement card:cards)if(id.equals(text(card.getAsJsonObject(),"id")))return card.getAsJsonObject();}return null;}
    private static JsonObject guard(JsonObject state,String id,Metadata reader) throws Exception {JsonObject result=reader.read(state,id);if(!"ok".equals(text(result,"status")) || !state.get("cycle").equals(result.get("cycle")))throw new IOException("CASTING_CASE_UNGUARDED");JsonObject entry=result.getAsJsonObject("objects").getAsJsonObject(id);if(entry==null)throw new IOException("CASTING_CASE_SOURCE_UNPROVEN");return entry;}
    public void before(JsonObject state,JsonObject prompt,JsonObject command) {
        viewer=text(state,"viewer");String kind=text(prompt,"kind");
        if(key.equals("casting-pile") && kind.equals("GAME_CHOOSE_PILE") && "boolean".equals(text(command,"kind"))){pileAnswered=true;pileFirst=command.get("value").getAsBoolean();for(int i=0;i<2;i++)for(JsonElement card:prompt.getAsJsonArray(i==0?"cards":"second_pile"))(pileFirst==(i==0)?pileChosen:pileRejected).add(text(card.getAsJsonObject(),"id"));}
if(kind.equals("GAME_PLAY_MANA")){payments++;if(!selected.isEmpty() && "object".equals(text(command,"kind"))){JsonObject source=locate(state,text(command,"value"),"battlefield");if(source!=null && text(source,"type").contains("Land"))paidSources.add(text(command,"value"));}if(new JsonPrimitive(false).equals(command.get("value"))){for(String id:selected.keySet())if(locate(state,id,"hand")!=null || locate(state,id,"battlefield")==null)cancelledSource=id;}}
        if(kind.equals("GAME_GET_AMOUNT") || kind.equals("GAME_GET_MULTI_AMOUNT"))numbers++;
        if(kind.equals("GAME_SELECT") && new JsonPrimitive(true).equals(prompt.get("is_priority")) && "object".equals(text(command,"kind"))){String id=text(command,"value");JsonObject source=locate(state,id,"hand");if(source!=null && name.equals(text(source,"name"))){selected.put(id,state.get("turn").getAsLong());if(key.equals("casting-search")){searchHand.clear();for(JsonElement held:state.getAsJsonArray("hand"))searchHand.add(text(held.getAsJsonObject(),"id"));for(JsonElement player:state.getAsJsonArray("players"))if(viewer.equals(text(player.getAsJsonObject(),"id")))searchLibrary=player.getAsJsonObject().get("library_count").getAsLong();searchTurn=state.get("turn").getAsLong();}}else if(locate(state,id,"battlefield")!=null && selected.containsKey(id))activated=true;}
    }
    public boolean observe(JsonObject state,JsonObject prompt,Metadata reader) throws Exception {
        long floating=0;for(JsonElement player:state.getAsJsonArray("players")){JsonObject seat=player.getAsJsonObject();if(viewer!=null && viewer.equals(text(seat,"id")) && seat.get("mana")!=null && seat.get("mana").isJsonArray())for(JsonElement pair:seat.getAsJsonArray("mana")){floating+=pair.getAsJsonArray().get(1).getAsLong();colorlessSeen|="colorless".equalsIgnoreCase(pair.getAsJsonArray().get(0).getAsString()) && pair.getAsJsonArray().get(1).getAsLong()>0;}}if(floating>0){floatingSeen=true;floatingTurn=state.get("turn").getAsLong();}
        if(cancelledSource!=null && locate(state,cancelledSource,"hand")!=null && new JsonPrimitive(true).equals(prompt.get("is_priority")))cancelled=true;
        for(JsonElement card:state.getAsJsonArray("stack")){String id=text(card.getAsJsonObject(),"id");JsonObject entry=guard(state,id,reader);String source=text(entry,"source");if(selected.containsKey(source) && entry.has("source_incarnation")){stacked.putIfAbsent(source,entry.get("source_incarnation").getAsLong());ownSpells.add(id);}if("Counterspell".equals(text(card.getAsJsonObject(),"name")) && new JsonPrimitive(true).equals(entry.get("stack_targets_complete"))){for(JsonElement target:entry.getAsJsonArray("stack_targets"))if(ownSpells.contains(target.getAsString())){counterTargeted=true;counterSource=source;counterIncarnation=entry.get("source_incarnation").getAsLong();}}}
        boolean flying=false,sacrificed=false;for(JsonElement player:state.getAsJsonArray("players"))for(JsonElement value:player.getAsJsonObject().getAsJsonArray("battlefield")){JsonObject card=value.getAsJsonObject();if("Memnite".equals(text(card,"name"))){JsonObject entry=guard(state,text(card,"id"),reader);if(viewer.equals(text(entry,"owner")) && viewer.equals(text(entry,"controller"))){if(creature==null){creature=text(card,"id");creatureIncarnation=entry.get("incarnation").getAsLong();}if(creature.equals(text(card,"id")) && entry.has("live_abilities"))for(JsonElement ability:entry.getAsJsonArray("live_abilities"))flying|=ability.getAsString().toLowerCase(Locale.ROOT).contains("flying");}}}
        if(creature!=null && locate(state,creature,"graveyard")!=null)sacrificed=guard(state,creature,reader).get("incarnation").getAsLong()==creatureIncarnation+1;
        int live=0;boolean counter=false,kicked=false;for(String id:selected.keySet()) {
            JsonObject source=locate(state,id,"battlefield");if(source==null){if(stacked.containsKey(id) && locate(state,id,"graveyard")!=null && guard(state,id,reader).get("incarnation").getAsLong()>stacked.get(id))verified=true;continue;}JsonObject entry=guard(state,id,reader);
            if(!viewer.equals(text(entry,"owner")) || !viewer.equals(text(entry,"controller")) || !name.equals(text(source,"name")))throw new IOException("CASTING_CASE_SOURCE_CHANGED");
            if(stacked.containsKey(id) && entry.get("incarnation").getAsLong()>stacked.get(id)){live++;verified=true;}
            kicked|="5".equals(text(source,"power")) && "5".equals(text(source,"toughness"));counter|="1".equals(text(source,"power")) && "1".equals(text(source,"toughness"));
        }
        boolean effect=false;if(key.equals("casting-ability") && activated)for(JsonElement player:state.getAsJsonArray("players"))if(!viewer.equals(text(player.getAsJsonObject(),"id")))effect=player.getAsJsonObject().get("life").getAsLong()==19;
        if(key.equals("casting-ability"))for(String id:stacked.keySet())if(locate(state,id,"graveyard")!=null){JsonObject entry=guard(state,id,reader);effect&=entry.get("incarnation").getAsLong()>stacked.get(id);}
        boolean differentTurns=selected.values().stream().distinct().count()>=2;
        boolean opponentDamaged=false;for(JsonElement player:state.getAsJsonArray("players"))if(!viewer.equals(text(player.getAsJsonObject(),"id")))opponentDamaged=player.getAsJsonObject().get("life").getAsLong()==19;
        boolean counterResolved=counterSource!=null && locate(state,counterSource,"graveyard")!=null && guard(state,counterSource,reader).get("incarnation").getAsLong()>counterIncarnation;
        if(key.equals("casting-search") && searchLibrary>=0 && state.get("turn").getAsLong()==searchTurn){boolean reduced=false;for(JsonElement player:state.getAsJsonArray("players"))if(viewer.equals(text(player.getAsJsonObject(),"id")))reduced=player.getAsJsonObject().get("library_count").getAsLong()==searchLibrary-1;if(reduced)for(JsonElement held:state.getAsJsonArray("hand")){JsonObject card=held.getAsJsonObject();if("Forest".equals(text(card,"name")) && !searchHand.contains(text(card,"id"))){JsonObject entry=guard(state,text(card,"id"),reader);searchVerified|=viewer.equals(text(entry,"owner")) && entry.get("incarnation").getAsLong()>0;}}}
        if(key.equals("casting-pile") && pileAnswered && pileChosen.size()+pileRejected.size()==5){pileVerified=true;for(String id:pileChosen)pileVerified&=locate(state,id,"hand")!=null;for(String id:pileRejected)pileVerified&=locate(state,id,"graveyard")!=null;}
        boolean lifePaid=false;for(JsonElement player:state.getAsJsonArray("players"))if(viewer.equals(text(player.getAsJsonObject(),"id")))lifePaid=player.getAsJsonObject().get("life").getAsLong()==18;
        boolean goal=key.equals("casting-x-zero")?verified && live==0 && numbers>0 && payments==0:key.equals("casting-pile")?verified && pileVerified:key.equals("casting-hybrid")?live==1 && paidSources.size()==1:key.equals("casting-phyrexian")?live==1 && paidSources.size()==1 && lifePaid:key.equals("casting-colorless")?live==1 && paidSources.size()==3 && colorlessSeen:key.equals("casting-kicker")?live==1 && paidSources.size()==5 && kicked:key.equals("casting-discount")?live==1 && paidSources.size()==3 && creature!=null && locate(state,creature,"battlefield")!=null:key.equals("casting-countered")?verified && live==0 && counterTargeted && counterResolved:key.equals("casting-search")?verified && searchVerified:key.equals("casting-modes")?verified && flying:key.equals("casting-additional")?verified && sacrificed && opponentDamaged:key.equals("casting-repeat")?live>=2 && differentTurns:key.equals("casting-cancel")?cancelled && live==1 && locate(state,cancelledSource,"battlefield")!=null:key.equals("casting-x")?live==1 && counter && numbers>0 && payments>=2:key.equals("casting-ability")?verified && activated && effect:key.equals("casting-floating")?live==1 && floatingSeen && floating==0 && selected.containsValue(floatingTurn):live==1;
        completed|=goal && state.getAsJsonArray("stack").size()==0 && new JsonPrimitive(true).equals(prompt.get("is_priority"));return completed;
    }
    public void terminal(String outcome) throws IOException {throw new IOException("CASTING_CASE_UNEXPECTED_TERMINAL");}
    public JsonObject report(){JsonObject result=new JsonObject();result.addProperty("native_casting_case",key);result.addProperty("native_casting_case_pile_verified",pileVerified);result.addProperty("native_casting_case_first_pile",pileFirst);result.addProperty("native_casting_case_manual_sources",paidSources.size());result.addProperty("native_casting_case_colorless_observed",colorlessSeen);result.addProperty("native_casting_case_completed",completed);result.addProperty("native_casting_case_source_verified",verified);result.addProperty("native_casting_case_stacked_sources",stacked.size());result.addProperty("native_casting_case_mana_responses",payments);result.addProperty("native_casting_case_numeric_responses",numbers);result.addProperty("native_casting_case_cancelled",cancelled);result.addProperty("native_casting_case_activated",activated);result.addProperty("native_casting_case_counter_targeted",counterTargeted);result.addProperty("native_casting_case_search_verified",searchVerified);result.addProperty("native_casting_case_floating_observed",floatingSeen);return result;}
}
